final storageProvider = FutureProvider<JsonSqFliteStorage>((ref) async => JsonSqFliteStorage.open(join(await getDatabasesPath(),'riverpod.db')));

class TodosNotifier extends AsyncNotifier<List<Todo>> {
  @override
  FutureOr<List<Todo>> build() async {
    await persist(
      ref.watch(storageProvider.future),
      key: 'todos',
      options: const StorageOptions(cacheTime: StorageCacheTime.unsafe_forever),
      encode: jsonEncode,
      decode: (json) => (jsonDecode(json) as List).map((e)=>Todo.fromJson(e as Map<String,Object?>)).toList(),
    ).future;
    return state.value ?? [];
  }
}
